def fill_color(grid, color):
    """Fill all 0s connected to any 0 inside a color region"""
    # Find min/max bounding box for each separate color group
    groups = {}

    # First find all unique positions for each color (excluding 0/background)
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and grid[r][c] not in groups:
                groups[grid[r][c]] = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}

    # For each color, extend bounding box to include any 0s between existing points
    filled_any = True
    while filled_any:
        filled_any = False
        for r in range(16):
            for c in range(15):
                if grid[r][c] == 0:
                    # Check if this cell is "inside" any color's bounds
                    for color_val, bbox in list(groups.items()):
