def flood_fill_component(grid, start_r, start_c):
    """Find all cells in same component as starting cell"""
    color = grid[start_r][start_c]
    visited = set()
    queue = [(start_r, start_c)]

    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited:
            continue
        visited.add((r, c))

        # Add neighbors of same color
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    queue.append((nr, nc))

    return visited, color

def fill_component_bounding_box(grid, visited):
    """Fill the bounding box of a component with its color"""
    positions = list(visited)
    min_r = min(p[0] for p in positions)
    max_r = max(p[0] for p in positions)
    min_c = min(p[1] for p in positions)
    max_c = max(p[1] for p in positions)

    color = grid[min_r][min_c]

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if 0 <= r < len(grid) and 0 <= c < len(grid[r]):
                # Only fill if it's within this component's bbox but not originally part of it
                if not ((r, c) in visited):
                    grid[r][c] = color

