def fill_hollow_interiors(grid):
    """Fill zeros that are completely surrounded by a single color"""

    # For each cell that is zero, check if it's surrounded by one color
    for r in range(16):
        for c in range(15):
            if grid[r][c] == 0:
                # Get colors of all orthogonal neighbors
                neighbor_colors = {}
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 16 and 0 <= nc < 15 and grid[nr][nc] != 0:
                        color = grid[nr][nc]
                        neighbor_colors[color] = neighbor_colors.get(color, 0) + 1

                # If exactly one color surrounds this cell
                if len(neighbor_colors) == 1:
                    color = list(neighbor_colors.keys())[0]
                    # Now do flood fill to find extent of enclosure
                    queue = [(r,c)]
                    enclosed = []
                    while queue:
                        cr, cc = queue.pop(0)
                        if (cr, cc) in enclosed:
                            continue
                        enclosed.append((cr, cc))

                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nnr, nnc = cr + dr, cc + dc
                            if 0 <= nnr < 16 and 0 <= nnc < 15:
                                if grid[nnr][nnc] == 0 and (nnr, nnc) not in enclosed:
                                    # Check if neighbors also have only this color
                                    temp_colors = {}
                                    for tdr, tdc in [(-1,0),(1,0),(0,-1),(0,1)]:
                                        tnr, tnc = nnr + tdr, nnc + tdc
                                        if 0 <= tnr < 16 and 0 <= tnc < 15 and grid[tnr][tnc] != 0:
                                            tc = grid[tnr][tnc]
                                            temp_colors[tc] = temp_colors.get(tc, 0) + 1
                                    if len(temp_colors) == 1 and list(temp_colors.keys())[0] == color:
                                        queue.append((nnr, nnc))

                    grid = mark_color(enclosed, color, grid)

    return grid

def mark_color(enclosed_cells, color, grid):
    """Mark all enclosed cells with given color"""
    for r, c in enclosed_cells:
        grid[r][c] = color
    return grid

